import numpy as np
import timeit
import time

# Define methods
def outer_np(vec1, vec2):
    return np.outer(vec1, vec2)

def outer_einsum(vec1, vec2):
    return np.einsum('i,j->ij', vec1, vec2)

def outer_broadcast(vec1, vec2):
    return vec1[:, None] * vec2[None, :]

def outer_matmul(vec1, vec2):
    # Reshape to column and row vectors, then matrix multiply
    return vec1[:, None] @ vec2[None, :]

# Test sizes
sizes = [10, 100, 1000, 10000]

for n in sizes:
    print(f"\nSize: {n}")
    vec1 = np.random.rand(n)
    vec2 = np.random.rand(n)
    # Warm up
    for func in [outer_np, outer_einsum, outer_broadcast, outer_matmul]:
        func(vec1, vec2)

    # Time each method
    for func in [outer_np, outer_einsum, outer_broadcast, outer_matmul]:
        stmt = lambda: func(vec1, vec2)
        time_taken = timeit.timeit(stmt, number=100) / 100
        print(f"{func.__name__}: {time_taken:.6f} seconds")
