import numpy as np
import numba as nb

class Solver:
    def __init__(self):
        # Pre-compile numba function for small vectors
        @nb.njit
def _outer_numba(vec1, vec2):
            n = len(vec1)
            m = len(vec2)
            result = np.empty((n, m), dtype=np.float64)
            for i in range(n):
                for j in range(m):
                    result[i, j] = vec1[i] * vec2[j]
            return result
        # Warm up with a small vector
        self._outer_numba = _outer_numba
        self._outer_numba(np.array([1.0, 2.0]), np.array([3.0, 4.0]))

    def solve(self, problem, **kwargs) -> np.ndarray:
        vec1, vec2 = problem
        # Convert to numpy arrays if needed
        vec1 = np.asarray(vec1, dtype=np.float64)
        vec2 = np.asarray(vec2, dtype=np.float64)
        n = len(vec1)
        # Use numba for small vectors
        if n <= 2000:
            return self._outer_numba(vec1, vec2)
        else:
            return np.outer(vec1, vec2)
